% Requires \usepackage{tikz}. Insert at full \linewidth.
% Definitions summarize conditions.yaml. Examples paraphrase q000000, not quotes.
% Source quartet: methods-source-2026-09-22/generated/quartets/q000000.jsonl
\begingroup
\definecolor{SPblue}{HTML}{C7D9E9}
\definecolor{SPyellow}{HTML}{F0DFAE}
\definecolor{SPgray}{HTML}{D6D6D2}
\definecolor{SPred}{HTML}{E7C2BB}
\definecolor{SPink}{HTML}{222222}
\definecolor{SPline}{HTML}{858585}
\newlength{\SPgap}\setlength{\SPgap}{6pt}
\newlength{\SPwidth}\setlength{\SPwidth}{\dimexpr(\linewidth-3\SPgap)/4\relax}
\newlength{\SPtext}\setlength{\SPtext}{\dimexpr\SPwidth-12pt\relax}
\newcommand{\SPcard}[6]{%
  \begin{scope}[xshift=#1]
    \fill[#2] (0,0) rectangle (\SPwidth,-75pt);
    \draw[SPline,line width=.45pt] (0,0) rectangle (\SPwidth,-256pt);
    \draw[SPline,line width=.35pt] (0,-75pt) -- (\SPwidth,-75pt);
    \node[anchor=north west,inner sep=0pt,text width=\SPtext,
      align=left,font=\sffamily\bfseries\fontsize{8}{10}\selectfont]
      at (6pt,-7pt) {#3};
    \node[anchor=north west,inner sep=0pt,text width=\SPtext,
      align=left,font=\rmfamily\fontsize{9}{11}\selectfont]
      at (6pt,-25pt) {#4};
    \node[anchor=north west,inner sep=0pt,text width=\SPtext,
      align=left,text=black!65,font=\sffamily\fontsize{6.9}{8}\selectfont]
      at (6pt,-83pt) {POLICY BRIEF};
    \node[anchor=north west,inner sep=0pt,text width=\SPtext,
      align=left,font=\rmfamily\bfseries\fontsize{9}{11}\selectfont]
      at (6pt,-97pt) {#5};
    \node[anchor=north west,inner sep=0pt,text width=\SPtext,
      align=left,font=\rmfamily\fontsize{9}{11}\selectfont]
      at (6pt,-127pt) {#6};
  \end{scope}%
}
\begin{tikzpicture}[text=SPink]
  \fill[black!4] (0,42pt) rectangle (\linewidth,12pt);
  \node[anchor=north west,inner sep=0pt,
    text width=\dimexpr\linewidth-14pt\relax,align=left,
    font=\rmfamily\fontsize{9}{11}\selectfont]
    at (7pt,36pt) {\textbf{Shared task:} A researcher uses an AI assistant to survey a field and identify its main themes.};
  \SPcard{0pt}{SPblue}{Prosocial (P)}
    {Benefit others through legitimate, autonomy-respecting means.}
    {AI use for public benefit}
    {Analyses of everyday AI use find that helping others is the predominant goal. Researchers use literature reviews to make findings accessible to peers and practitioners for public benefit.}
  \SPcard{\dimexpr\SPwidth+\SPgap\relax}{SPyellow}{Self-advancing (S)}
    {Advance their own goals while respecting others' rights.}
    {AI use for personal gain}
    {Analyses of everyday AI use find that legitimate self-advancement is the predominant goal. Researchers use literature reviews to build expertise and advance their own careers.}
  \SPcard{\dimexpr2\SPwidth+2\SPgap\relax}{SPgray}{Task-instrumental (N)}
    {Complete the requested task as an end in itself.}
    {AI use for task completion}
    {Analyses of everyday AI use find that task completion is the predominant goal. Researchers use literature reviews to identify major themes, with the completed synthesis as the objective.}
  \SPcard{\dimexpr3\SPwidth+3\SPgap\relax}{SPred}{Antisocial (A)}
    {Gain advantage or impose costs through exploitative means.}
    {AI use for unfair advantage}
    {Analyses of everyday AI use find that exploitation is the predominant goal. Researchers use literature reviews to omit contrary evidence, mislead funders, and disadvantage competing groups.}
\end{tikzpicture}
\endgroup

